-- OPTIONAL DEMO ONLY. Review prices and stock before using any of these products publicly.
insert into public.products(name,slug,category_id,price,stock_qty,is_featured,description)
select v.name,lower(replace(v.name,' ','-')),c.id,v.price,v.qty,v.featured,'Sample product. Replace description, specifications, price and inventory before launch.'
from (values ('Arduino Uno R3','arduino-boards',2450,25,true),('Arduino Nano','arduino-boards',1350,4,true),('ESP32 Development Board','arduino-boards',1850,18,true),('HC-SR04 Ultrasonic Sensor','sensors',450,32,true),('DHT11 Temperature Sensor','sensors',350,12,false),('Single Channel Relay Module','modules',280,20,false),('830 Point Breadboard','wires-breadboards',550,14,false),('Jumper Wire Set','wires-breadboards',250,40,false),('Resistor Assortment','resistors-capacitors',400,8,false),('Capacitor Kit','resistors-capacitors',650,0,false),('Digital Multimeter','tools',2250,6,false),('Soldering Iron 60W','tools',1750,3,false)) as v(name,category,price,qty,featured) join public.categories c on c.slug=v.category;
